package thaumcraft.thaumaturgy;
import java.util.*;
import com.mojang.serialization.JsonOps;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class FocusCanvasTest {
 static FocusProgram leaf(String medium,String effect){return new FocusProgram(medium,List.of(new FocusProgram.Effect(effect,1,1)));}
 @Test void selectionAddressesIdentifyEveryEffectAndContinuationWithoutChangingSibling(){var graph=leaf("projectile","air").modifier("split_trajectory").withChild(0,leaf("bolt","fire")).withChild(1,leaf("touch","heal"));var nodes=FocusCanvas.nodes(graph);assertTrue(nodes.size()<=FocusCanvas.LAST_SELECT-FocusCanvas.FIRST_SELECT+1);var selected=nodes.stream().filter(n->n.kind()==FocusCanvas.EFFECT&&n.name().equals("heal")).findFirst().orElseThrow();assertEquals(List.of(1),selected.address());assertEquals(0,selected.branch());assertEquals(0,selected.effect());var changed=graph.replaceAt(selected.address(),leaf("touch","frost"));assertEquals(graph.child(0),changed.child(0));assertEquals("frost",changed.child(1).effects().getFirst().kind());for(int i=0;i<nodes.size();i++)assertTrue(nodes.get(i).parent()<i);}
 @Test void intermediateMediaNeedNoArtificialEffectAndKeepTheirOwnCosts(){var sequence=new FocusProgram("projectile",List.of()).withChild(0,leaf("bolt","fire"));assertTrue(sequence.valid());assertEquals(1,sequence.totalEffects());assertEquals(Map.of("motus",1,"potentia",1,"ignis",1),sequence.crystals());assertEquals(12,sequence.complexity());assertEquals(sequence,FocusProgram.CODEC.parse(JsonOps.INSTANCE,FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,sequence).getOrThrow()).getOrThrow());assertFalse(new FocusProgram("touch",List.of()).valid());assertFalse(sequence.withChild(0,null).valid());}
 @Test void selectionProjectionIsDeterministicAndHasNoOverlappingNodes(){var graph=leaf("projectile","air").modifier("split_target").withChild(0,leaf("bolt","fire").modifier("scatter")).withChild(1,leaf("touch","heal"));var nodes=FocusCanvas.nodes(graph);assertEquals(nodes,FocusCanvas.nodes(graph));var cells=new HashSet<String>();for(var n:nodes)assertTrue(cells.add(n.x()+":"+n.y()));assertTrue(nodes.stream().anyMatch(n->n.name().equals("impact")));}
 @Test void aWholeEightStageSequenceFitsTheSelectionProtocolAndRoundTrips(){var graph=leaf("touch","air");for(int i=1;i<8;i++)graph=new FocusProgram("touch",List.of()).withChild(0,graph);assertTrue(graph.valid());assertEquals(1,graph.totalEffects());assertEquals(8,graph.graphNodes().size());assertEquals(9,FocusCanvas.nodes(graph).size());assertEquals(graph,FocusProgram.CODEC.parse(JsonOps.INSTANCE,FocusProgram.CODEC.encodeStart(JsonOps.INSTANCE,graph).getOrThrow()).getOrThrow());assertFalse(new FocusProgram("touch",List.of()).withChild(0,graph).valid());}
}
